package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.junit.jupiter.api.io.TempDir;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.Import;import org.springframework.transaction.annotation.Transactional;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@SpringBootTest @Import(LegacyBankJdbcTestConfiguration.class) @Transactional("legacyBankTestTransactions") @EnabledIfEnvironmentVariable(named="PETLIS_LOCAL_DB_TEST",matches="true")
class LegacyHospitalReportLocalDatabaseTest {
 @Autowired FeatureStore store;@TempDir Path root;LegacyHospitalHistoryLocalDatabaseTest f;LegacyHospitalReportService service;long detail;
 @BeforeEach void setup()throws Exception{f=new LegacyHospitalHistoryLocalDatabaseTest();f.store=store;f.setup();long species=store.insert("INSERT INTO lin_lb_infoanimal(AnimalName,AnimalName_en,IsActive) VALUES(?,?,1)",f.f.prefix,f.f.prefix);store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET InfoAnimalId=? WHERE ListDiagnosisProjectId=?",species,f.f.order);f.gate("{\"enabled\":true,\"reportDownloadEnabled\":true}");f.f.detail(f.f.test,"8.25",1,0);detail=((Number)store.one("SELECT DiagnosisDetailId FROM lin_lb_diagnosisdetail WHERE ListDiagnosisProjectId=?",f.f.order).get("DiagnosisDetailId")).longValue();store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET SampleStatus=2,IsPayMoney=0 WHERE ListDiagnosisProjectId=?",f.f.order);store.jdbc().update("UPDATE lin_lb_diagnosisdetail SET IsSendMail=1,PDFHttpUrl='/Content/FilePdf/owned.pdf' WHERE DiagnosisDetailId=?",detail);Files.write(root.resolve("owned.pdf"),LegacyReportFileReaderTest.PDF);service=new LegacyHospitalReportService(store,f.f.access,f.service,mock(PlatformFileService.class),new LegacyReportFileReader(root.toString(),1024),new LegacyCustomerViewService(store,f.f.access,new LegacyReportLinks("","")));}
 @Test void ownSentReportReturnsExactPrivatePdfWithUnpaidParentMarkerAndNoDebtEvenWhenCancelled(){var before=store.one("SELECT * FROM lin_lb_diagnosisdetail WHERE DiagnosisDetailId=?",detail);var response=service.download(detail,(int)f.f.hospital);assertArrayEquals(LegacyReportFileReaderTest.PDF,(byte[])response.getBody());assertEquals("private, no-store",response.getHeaders().getFirst("Cache-Control"));assertEquals("nosniff",response.getHeaders().getFirst("X-Content-Type-Options"));assertEquals(before,store.one("SELECT * FROM lin_lb_diagnosisdetail WHERE DiagnosisDetailId=?",detail));store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET SampleStatus=4 WHERE ListDiagnosisProjectId=?",f.f.order);assertArrayEquals(LegacyReportFileReaderTest.PDF,(byte[])service.download(detail,(int)f.f.hospital).getBody());}
 @Test void cashDebtAcrossSiblingDetailsBlocksEvenWhenParentMarkedPaid(){
  store.jdbc().update("UPDATE lin_lb_infohospital SET PayType=0 WHERE InfoHospitalId=?",f.f.hospital);
  store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET ReceiveSampleDt='2020-01-01',IsPayMoney=1 WHERE ListDiagnosisProjectId=?",f.f.order);
  f.f.detail(f.f.test,"2.50",0,0);
  assertEquals(409,assertThrows(BusinessException.class,()->service.download(detail,(int)f.f.hospital)).getCode());
 }
 @Test void monthlyZeroPriceDebtStillBlocksByExistence(){
  store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET ReceiveSampleDt='2020-01-01' WHERE ListDiagnosisProjectId=?",f.f.order);
  store.jdbc().update("UPDATE lin_lb_diagnosisdetail SET TestPrice=0,PayStatus2=0,IsCheckPass=0 WHERE DiagnosisDetailId=?",detail);
  assertEquals(409,assertThrows(BusinessException.class,()->service.download(detail,(int)f.f.hospital)).getCode());
 }

 @Test void wrongHospitalUnsentAndUnreviewedAndClosedFlagsCannotRead(){assertEquals(403,assertThrows(BusinessException.class,()->service.download(detail,2147483647)).getCode());store.jdbc().update("UPDATE lin_lb_diagnosisdetail SET IsSendMail=0 WHERE DiagnosisDetailId=?",detail);assertEquals(409,assertThrows(BusinessException.class,()->service.download(detail,(int)f.f.hospital)).getCode());store.jdbc().update("UPDATE lin_lb_diagnosisdetail SET IsSendMail=1 WHERE DiagnosisDetailId=?",detail);store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET SampleStatus=0 WHERE ListDiagnosisProjectId=?",f.f.order);assertEquals(409,assertThrows(BusinessException.class,()->service.download(detail,(int)f.f.hospital)).getCode());f.gate("{\"enabled\":true,\"reportDownloadEnabled\":\"true\"}");assertEquals(409,assertThrows(BusinessException.class,()->service.download(detail,(int)f.f.hospital)).getCode());}
 @Test void missingFileIsExplicitAndDoesNotGenerateSubstitute()throws Exception{Files.delete(root.resolve("owned.pdf"));assertEquals(404,assertThrows(BusinessException.class,()->service.download(detail,(int)f.f.hospital)).getCode());assertFalse(Files.exists(root.resolve("owned.pdf")));}
 @Test void newWorkflowCannotExposeDraftUsingOldLocalFile(){store.insert("INSERT INTO lin_report_workflow(order_id,detail_id,test_result_id,hospital_id,laboratory_id,status) VALUES(?,?,0,?,0,'DRAFT')",f.f.order,detail,f.f.hospital);assertEquals(409,assertThrows(BusinessException.class,()->service.download(detail,(int)f.f.hospital)).getCode());}
 @Test void publishedWorkflowUsesOnlyItsOwnBoundFile()throws Exception{var platform=new PlatformFileService(store,f.f.access,mock(com.petlis.common.security.ReviewPermission.class),root.toString(),1024);long id=store.insert("INSERT INTO lin_report_workflow(order_id,detail_id,test_result_id,hospital_id,laboratory_id,status) VALUES(?,?,0,?,0,'PUBLISHED')",f.f.order,detail,f.f.hospital);var saved=platform.saveReport((int)f.f.hospital,0,id,LegacyReportFileReaderTest.PDF);store.jdbc().update("UPDATE lin_report_workflow SET pdf_file_id=? WHERE id=?",saved.id(),id);service=new LegacyHospitalReportService(store,f.f.access,f.service,platform,new LegacyReportFileReader(root.toString(),1024),new LegacyCustomerViewService(store,f.f.access,new LegacyReportLinks("","")));var response=service.download(detail,(int)f.f.hospital);try(var input=((org.springframework.core.io.Resource)response.getBody()).getInputStream()){assertArrayEquals(LegacyReportFileReaderTest.PDF,input.readAllBytes());}store.jdbc().update("UPDATE lin_file SET biz_id='other-report' WHERE id=?",saved.id());assertEquals(409,assertThrows(BusinessException.class,()->service.download(detail,(int)f.f.hospital)).getCode());}

}
